function validate([lowLimit, highLimit]) {
  if (!Number.isInteger(lowLimit) || !Number.isInteger(highLimit)) return 'Both limits are whole numbers.';
  if (lowLimit < 1) return 'lowLimit is at least 1.';
  if (highLimit > 100000) return 'highLimit is at most 100000.';
  if (lowLimit > highLimit) return 'lowLimit cannot be larger than highLimit.';
  return null;
}

