function countBalls(lowLimit, highLimit) {
  const boxes = new Array(46).fill(0);
  let best = 0;
  for (let ball = lowLimit; ball <= highLimit; ball++) {
    let box = 0;
    let rest = ball;
    while (rest > 0) {
      box += rest % 10;
      rest = Math.floor(rest / 10);
    }
    boxes[box]++;
    best = Math.max(best, boxes[box]);
  }
  return best;
}

