function countBalls(lowLimit, highLimit) {
  const tally = new Map();
  for (let n = lowLimit; n <= highLimit; n++) {
    const key = String(n).split('').reduce((acc, ch) => acc + Number(ch), 0);
    tally.set(key, (tally.get(key) || 0) + 1);
  }
  return Math.max(...tally.values());
}

