function generate(rand, size) {
  if (size === 'large') {
    const lowLimit = 1 + Math.floor(rand() * 20000);
    const highLimit = Math.max(lowLimit, 100000 - Math.floor(rand() * 20000));
    return [lowLimit, highLimit];
  }
  const pick = rand();
  const lowLimit = pick < 0.3 ? 1 + Math.floor(rand() * 20) : pick < 0.6 ? 1 + Math.floor(rand() * 2000) : 99800 + Math.floor(rand() * 200);
  const highLimit = Math.min(100000, lowLimit + Math.floor(rand() * 120));
  return [lowLimit, highLimit];
}
